// RFC 4648 §5 base64url encoding/decoding, no padding.
// Pure JS — no external dependencies.

const ALPHABET = 'ABCDEFGHIJKLMNOPQRSTUVWXYZabcdefghijklmnopqrstuvwxyz0123456789-_';

const REVERSE = (() => {
  const table = new Int8Array(128).fill(-1);
  for (let i = 0; i < ALPHABET.length; i++) {
    table[ALPHABET.charCodeAt(i)] = i;
  }
  return table;
})();

export function b64urlEncode(bytes) {
  let out = '';
  let i = 0;
  for (; i + 3 <= bytes.length; i += 3) {
    const n = (bytes[i] << 16) | (bytes[i + 1] << 8) | bytes[i + 2];
    out += ALPHABET[(n >> 18) & 63] +
           ALPHABET[(n >> 12) & 63] +
           ALPHABET[(n >> 6) & 63] +
           ALPHABET[n & 63];
  }
  const rem = bytes.length - i;
  if (rem === 1) {
    const n = bytes[i] << 16;
    out += ALPHABET[(n >> 18) & 63] + ALPHABET[(n >> 12) & 63];
  } else if (rem === 2) {
    const n = (bytes[i] << 16) | (bytes[i + 1] << 8);
    out += ALPHABET[(n >> 18) & 63] +
           ALPHABET[(n >> 12) & 63] +
           ALPHABET[(n >> 6) & 63];
  }
  return out;
}

export function b64urlDecode(str) {
  const s = String(str).replace(/=+$/, ''); // tolerate padding, accept unpadded
  const out = [];
  let acc = 0;
  let nbits = 0;
  for (let i = 0; i < s.length; i++) {
    const code = s.charCodeAt(i);
    const v = code < 128 ? REVERSE[code] : -1;
    if (v < 0) {
      throw new Error('Invalid base64url character: ' + s[i]);
    }
    acc = (acc << 6) | v;
    nbits += 6;
    if (nbits >= 8) {
      nbits -= 8;
      out.push((acc >> nbits) & 0xff);
    }
  }
  return new Uint8Array(out);
}

// Python json.dumps(obj, separators=(',', ':'), ensure_ascii=True) semantics
// for the JSON subset: strings, numbers, booleans, null, arrays, plain objects.

// Short escape forms used by Python's json encoder for control characters.
const SHORT_ESCAPES = {
  0x08: '\\b',
  0x09: '\\t',
  0x0a: '\\n',
  0x0c: '\\f',
  0x0d: '\\r',
};

function encodeString(s) {
  let out = '"';
  for (const ch of s) { // iterates by code point
    const cp = ch.codePointAt(0);
    if (ch === '"') {
      out += '\\"';
    } else if (ch === '\\') {
      out += '\\\\';
    } else if (cp < 0x20) {
      out += SHORT_ESCAPES[cp] || '\\u' + cp.toString(16).padStart(4, '0');
    } else if (cp < 0x80) {
      out += ch; // 0x7f (DEL) is NOT escaped by ensure_ascii
    } else if (cp < 0x10000) {
      out += '\\u' + cp.toString(16).padStart(4, '0');
    } else {
      // astral plane: UTF-16 surrogate pair, each half escaped
      const v = cp - 0x10000;
      const hi = 0xd800 + (v >> 10);
      const lo = 0xdc00 + (v & 0x3ff);
      out += '\\u' + hi.toString(16).padStart(4, '0') +
             '\\u' + lo.toString(16).padStart(4, '0');
    }
  }
  return out + '"';
}

function encodeNumber(n) {
  if (Number.isInteger(n)) {
    return String(n);
  }
  // Non-integer floats are out of scope for this subset; JS shortest repr
  // matches Python repr for ordinary values (e.g. 1.5 -> "1.5").
  return String(n);
}

export function pyJsonDumps(value) {
  if (value === null || value === undefined) {
    return 'null';
  }
  if (typeof value === 'boolean') {
    return value ? 'true' : 'false';
  }
  if (typeof value === 'number') {
    return encodeNumber(value);
  }
  if (typeof value === 'string') {
    return encodeString(value);
  }
  if (Array.isArray(value)) {
    return '[' + value.map(pyJsonDumps).join(',') + ']';
  }
  if (typeof value === 'object') {
    // Object.keys preserves insertion order for string keys,
    // matching Python dict ordering.
    const entries = Object.keys(value).map(
      (k) => encodeString(k) + ':' + pyJsonDumps(value[k])
    );
    return '{' + entries.join(',') + '}';
  }
  throw new TypeError('pyJsonDumps: unsupported type: ' + typeof value);
}

// Python repr() semantics for the subset: strings, numbers, booleans,
// null (None), arrays (lists), plain objects (dicts).

// A character is non-printable (per Python str.isprintable) when it is in a
// Unicode "Other" (C*) or "Separator" (Z*) category — except U+0020 SPACE.
const NON_PRINTABLE = /[\p{C}\p{Z}]/u;

function isPrintable(ch) {
  if (ch === ' ') return true;
  return !NON_PRINTABLE.test(ch);
}

function reprString(s) {
  const hasSingle = s.includes("'");
  const hasDouble = s.includes('"');
  // Python prefers single quotes; switch to double quotes only when the
  // string contains a single quote but no double quote.
  const quote = hasSingle && !hasDouble ? '"' : "'";
  let out = quote;
  for (const ch of s) { // iterates by code point
    const cp = ch.codePointAt(0);
    if (ch === '\\') {
      out += '\\\\';
    } else if (ch === quote) {
      out += '\\' + quote;
    } else if (ch === '\n') {
      out += '\\n';
    } else if (ch === '\t') {
      out += '\\t';
    } else if (ch === '\r') {
      out += '\\r';
    } else if (isPrintable(ch)) {
      out += ch; // printable non-ASCII (é, 中, emoji) printed literally
    } else if (cp <= 0xff) {
      out += '\\x' + cp.toString(16).padStart(2, '0');
    } else if (cp <= 0xffff) {
      out += '\\u' + cp.toString(16).padStart(4, '0');
    } else {
      out += '\\U' + cp.toString(16).padStart(8, '0');
    }
  }
  return out + quote;
}

function reprNumber(n) {
  if (Number.isInteger(n)) {
    return String(n);
  }
  return String(n);
}

export function pyRepr(value) {
  if (value === null || value === undefined) {
    return 'None';
  }
  if (typeof value === 'boolean') {
    return value ? 'True' : 'False';
  }
  if (typeof value === 'number') {
    return reprNumber(value);
  }
  if (typeof value === 'string') {
    return reprString(value);
  }
  if (Array.isArray(value)) {
    return '[' + value.map(pyRepr).join(', ') + ']';
  }
  if (typeof value === 'object') {
    const entries = Object.keys(value).map(
      (k) => reprString(k) + ': ' + pyRepr(value[k])
    );
    return '{' + entries.join(', ') + '}';
  }
  throw new TypeError('pyRepr: unsupported type: ' + typeof value);
}

