// A character is non-printable (per Python str.isprintable) when it is in a
// Unicode "Other" (C*) or "Separator" (Z*) category — except U+0020 SPACE.
const NON_PRINTABLE = /[\p{C}\p{Z}]/u;

// Code points first assigned in Unicode 15.1. Node's Unicode tables are newer
// than CPython 3.12's (Unicode 15.0.0), which still treats these as unassigned
// (Cn) and therefore non-printable in repr(). The bulk is CJK Extension I.
function isUnicode151Addition(cp) {
  return (cp >= 0x2ebf0 && cp <= 0x2ee5d) || // CJK Unified Ideographs Ext I
         cp === 0x0cf3 || cp === 0x0ece ||
         (cp >= 0x10efd && cp <= 0x10eff) ||
         (cp >= 0x11b00 && cp <= 0x11b09) ||
         cp === 0x1b4e || cp === 0x1b4f;
}

function isPrintable(ch) {
  if (ch === ' ') return true;
  if (isUnicode151Addition(ch.codePointAt(0))) return false;
  return !NON_PRINTABLE.test(ch);
}

